script:
carrier_event = {
	id = colony.1500
	title = "colony.1500.name"
	desc = "colony.1500.desc"
	picture = GFX_evt_asteroid_approaching_planet
	location = ROOT
	trackable = yes

	pre_triggers = {
		has_owner = yes
		is_homeworld = no
		original_owner = yes
		is_ai = no
		has_ground_combat = no
		is_capital = no
		is_occupied_flag = no
	}

	trigger = {
		owner = {
			NOT = { has_country_flag = FLDrone_country }
			is_wilderness_empire = no
		}
		pop_amount > 0
		NOR = {
			is_planet_class = pc_habitat
			has_carrier_flag = colony_event
			has_carrier_flag = FLDrone_event
		}
		has_moon = yes
		any_moon = {
			habitable_planet = no
		}
	}

	is_triggered_only = yes

	immediate = {
		set_carrier_flag = FLDrone_event
		set_carrier_flag = colony_event
		owner = { set_country_flag = FLDrone_country }
	}

	option = {
		name = colony.1500.a
		enable_special_project = {
			name = "HELPFUL_DRONES_1_PROJECT"
			location = this
			owner = root.owner
		}
	}
}

